css:
/* 「新刊」区画の中を全部大きく（区画の見出しが「新刊」のもの。NEW にしているなら "NEW" に書き換え） */
.sheet .grp[data-label="新刊"] { font-size: 1.3em; }

/* キラキラ（✦）を背景に散らす */
/* 線や箱より後ろ、背景の模様より前に出ます。
   1つ分 = var(--kira) no-repeat 横の位置 縦の位置 / 大きさ 。増やすときはカンマで区切って足す
   色を変えるときは fill='%23e8562a' の e8562a を別の色コードに */
.sheet::after {
  content: ""; position: absolute; inset: 0; z-index: 0; pointer-events: none;
  --kira: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 20 20'><path d='M10 0C10.6 8 12 9.4 20 10C12 10.6 10.6 12 10 20C9.4 12 8 10.6 0 10C8 9.4 9.4 8 10 0Z' fill='%23e8562a'/></svg>");
  background:
    var(--kira) no-repeat 95% 16% / 14mm,
    var(--kira) no-repeat 4% 47% / 10mm,
    var(--kira) no-repeat 52% 60% / 7mm,
    var(--kira) no-repeat 96% 93% / 12mm;
}

/* テーマ「報告書」のCSSを書き出したもの。数字や色を書き換えると反映されます。
   消せばテーマ本来の見た目に戻ります */
/* ===== 共通（よく編集するところ） ===== */
/* 頒布物のタイトル */
.title {
  font-family: var(--f-head);
  font-size: calc(2.3em * var(--title-k,1));
  line-height: 1.15;
  margin: 0px;
  font-weight: 900;
  white-space: pre-wrap;
}
/* 詳細（判型・ページ数） */
.spec {
  font-weight: 700;
  font-size: calc(1.25em * var(--text-k,1));
  white-space: pre-wrap;
}
/* カップリング */
.cp {
  font-weight: 700;
  font-size: calc(1.05em * var(--text-k,1));
  white-space: pre-wrap;
}
/* 説明文 */
.desc {
  font-size: calc(1em * var(--text-k,1));
  margin: 0.3em 0px 0px;
  white-space: pre-wrap;
  line-height: 1.55;
  font-weight: 700;
}
/* 注意書き（小さい文字） */
.note {
  font-size: calc(.72em * var(--text-k,1));
  white-space: pre-wrap;
}
/* 値段 */
.price {
  margin-top: auto;
  padding-top: 0.1em;
  align-self: flex-end;
  font-family: var(--f-num);
  font-size: calc(4.2em * var(--price-fit,1) * var(--price-k,1));
  font-weight: 900;
  line-height: 1;
  white-space: nowrap;
}
/* 値段の「円」 */
.price .unit {
  font-size: 0.5em;
  margin-left: 0.05em;
}
/* 頒布物のバッジ（新刊・R-18 などの小さい札） */
.badge {
  display: inline-block;
  font-weight: 900;
  line-height: 1.2;
  padding: 0.12em 0.5em;
  border: 0.14em solid;
  border-radius: 0.3em;
  font-size: 0.95em;
}
/* 「新刊」バッジ */
.badge.new {
  background: var(--c-ink);
  border-color: var(--c-ink);
  color: var(--c-bg);
}
/* 「R-18」バッジ */
.badge.r18 {
  background: var(--c-accent);
  border-color: var(--c-accent);
  color: rgb(255, 255, 255);
  margin-right: 0.3em;
  font-family: var(--f-num);
}
/* 区画の見出し（新刊・既刊など） */
.grp-badge {
  display: inline-block;
  font-family: var(--f-head);
  font-weight: 900;
  line-height: 1.1;
  color: var(--grp-fg);
  background: var(--grp-bg);
  font-size: calc(2.2em * var(--grp-k,1));
}
/* 区画のサブ文字（残部少！など） */
.grp-sub {
  font-family: var(--f-head);
  font-weight: 900;
  font-style: italic;
  font-size: 1.7em;
  color: var(--grp-bg);
}

/* ===== テーマ「報告書」 ===== */
/* キャッチ（全部新刊!! など） */
.theme-frame .headline, .theme-report .headline {
  position: absolute;
  z-index: 2;
  top: 16mm;
  right: 16mm;
  max-width: 46%;
  margin: 0px;
  background: var(--c-ink);
  color: var(--c-paper);
  clip-path: var(--burst);
  padding: 1.3em 1.9em;
  font-size: calc(3.2em * var(--hs) * var(--hl-k,1));
  rotate: -4deg;
}
/* 用紙全体（背景色・文字色・余白など） */
.theme-report {
  padding: 16mm 18mm;
}
/* ヘッダー全体（日付〜サークル名の並び、下の線など） */
.theme-report .sh {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 10mm;
  align-items: end;
  margin-bottom: 10mm;
  padding-bottom: 6mm;
  border-bottom: .5mm solid var(--c-ink);
}
/* 日付・イベント名・スペースの入れ物 */
.theme-report .sh-box {
  border: .5mm solid var(--c-ink);
  background: var(--c-paper);
  padding: 4mm 8mm;
}
/* 日付 */
.theme-report .sh-date {
  font-family: var(--f-num);
  font-weight: 700;
  font-size: 1.8em;
  line-height: 1.1;
}
/* イベント名 */
.theme-report .sh-event {
  font-weight: 700;
  letter-spacing: 0.25em;
  font-size: 1.1em;
}
/* スペース番号 */
.theme-report .sh-space {
  font-family: var(--f-num);
  font-weight: 700;
  font-size: 7em;
  line-height: 1;
}
/* サークル名 */
.theme-report .sh-circle {
  font-family: var(--f-circle,var(--f-head));
  font-size: calc(5em * var(--circle-k,1));
  line-height: 1;
  text-align: right;
  font-weight: 900;
}
/* キャッチ（全部新刊!! など） */
.theme-report .headline {
  top: auto;
  bottom: 14mm;
  right: 14mm;
  background: var(--c-sub);
  color: rgb(255, 242, 0);
  rotate: -8deg;
  font-family: var(--f-num);
}
/* 頒布物の文字部分の入れ物（タイトル〜説明） */
.theme-report .info-main {
  background: var(--c-accent);
  color: rgb(255, 255, 255);
  padding: 0.6em 0.8em 0.7em;
  border: .5mm solid var(--c-ink);
  margin-right: 100px;
}
/* 頒布物のタイトル */
.theme-report .title {
  font-size: calc(2.1em * var(--title-k,1));
}
/* 「新刊」バッジ */
.theme-report .badge.new {
  background: var(--c-sub);
  border-color: var(--c-sub);
  color: rgb(255, 242, 0);
  font-family: var(--f-num);
}
/* 「R-18」バッジ */
.theme-report .badge.r18 {
  background: rgb(255, 255, 255);
  border-color: rgb(255, 255, 255);
  color: var(--c-accent);
}
/* 値段 */
.theme-report .price {
  position: relative;
  margin-top: auto;
  border: .5mm solid var(--c-ink);
  background: var(--c-paper);
  padding: 0.2em 0.4em 0.12em 0.45em;
  line-height: 1;
  font-weight: 700;
}
/* 値段の前につく飾り */
.theme-report .price::before {
  content: "";
  position: absolute;
  left: 0.15em;
  top: 0px;
  width: 0.75em;
  height: 0.1em;
  border-right-color:;
  border-right-style:;
  border-right-width:;
  border-bottom-color:;
  border-bottom-style:;
  border-bottom-width:;
  border-left-color:;
  border-left-style:;
  border-left-width:;
  border-image-source:;
  border-image-slice:;
  border-image-width:;
  border-image-outset:;
  border-image-repeat:;
  border-top: 0px;
}
/* 値段の「円」 */
.theme-report .price .unit {
  font-family: var(--f-body);
  font-weight: 700;
  font-size: 0.42em;
  margin-left: 0.12em;
}
/* 値段欄に「無料配布」など文字を書いたとき */
.theme-report .price.text {
  font-family: var(--f-body);
  padding: 0.3em 0.5em 0.25em;
}
/* 頒布物の画像と仮画像（表紙まだ） */
.theme-report .img :is(img, .ph) {
  filter: drop-shadow(1.2mm 1.2mm 0 var(--c-ink));
}
/* 区画の見出しの色（見出しの色を「テーマの色」にしたとき。--grp-bg が塗り、--grp-fg が文字色） */
.theme-report .grp-auto {
  --grp-bg: var(--c-sub);
  --grp-fg: #fff200;
}
